<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>FitPulse | Transaction Details</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="{{ asset('css/style.css') }}"></head>
<body class="bg-light"><nav class="navbar navbar-dark navbar-emerald"><div class="container"><a class="navbar-brand fw-bold" href="{{ route('dashboard') }}">FitPulse Inventory</a><a class="btn btn-outline-light btn-sm" href="{{ route('transactions.index') }}">All Transactions</a></div></nav>
<main class="container py-4"><div class="card border-0 shadow-sm mx-auto" style="max-width:720px"><div class="card-body p-4"><h1 class="h3 fw-bold">Transaction #{{ $transaction->id }}</h1><p class="text-muted">Recorded {{ optional($transaction->created_at)->format('M d, Y H:i:s') }}</p><dl class="row mb-0"><dt class="col-sm-4">Product</dt><dd class="col-sm-8">{{ optional($transaction->product)->name ?? 'Deleted product' }}</dd><dt class="col-sm-4">SKU</dt><dd class="col-sm-8">{{ optional($transaction->product)->sku ?? '—' }}</dd><dt class="col-sm-4">Type</dt><dd class="col-sm-8">{{ strtoupper($transaction->type) }}</dd><dt class="col-sm-4">Quantity / new count</dt><dd class="col-sm-8">{{ number_format($transaction->quantity) }}</dd><dt class="col-sm-4">Quantity before</dt><dd class="col-sm-8">{{ number_format($transaction->quantity_before) }}</dd><dt class="col-sm-4">Quantity after</dt><dd class="col-sm-8">{{ number_format($transaction->quantity_after) }}</dd><dt class="col-sm-4">Reference</dt><dd class="col-sm-8">{{ $transaction->reference ?: '—' }}</dd><dt class="col-sm-4">Notes / reason</dt><dd class="col-sm-8">{{ $transaction->notes ?: '—' }}</dd><dt class="col-sm-4">Recorded by</dt><dd class="col-sm-8">{{ $transaction->actor_name ?: 'System' }}</dd></dl><a href="{{ route('transactions.index') }}" class="btn btn-success mt-3">Back to History</a></div></div></main></body></html>
